import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { mkdirSync, writeFileSync, rmSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { generateBriefing } from "../../src/briefing/agent-context.js";

function makeMgmtDir(taskId: string, featureId: string, title: string): string {
  const dir = join(tmpdir(), `briefing-test-${Date.now()}-${Math.random().toString(36).slice(2)}`);
  const tasksDir = join(dir, "docs", "features", featureId, "tasks");
  mkdirSync(tasksDir, { recursive: true });
  writeFileSync(
    join(tasksDir, `${taskId}.yaml`),
    `id: ${taskId}\ntitle: ${title}\nrepo: workflow\nstatus: ready\n`,
    "utf-8",
  );
  return dir;
}

describe("generateBriefing", () => {
  let mgmtDir: string;

  beforeEach(() => {
    mgmtDir = makeMgmtDir("T4", "executor-self-briefing", "Claude executor — self-briefing module");
  });

  afterEach(() => {
    rmSync(mgmtDir, { recursive: true, force: true });
  });

  it("returns a string containing the task title from the YAML", () => {
    const result = generateBriefing(mgmtDir, {
      taskId: "T4",
      featureId: "executor-self-briefing",
      taskBranch: "feature/executor-self-briefing-T4",
      taskRepo: "workflow",
      taskRepoRoot: "/impl",
      workspaceRoot: mgmtDir,
      gitAuthorEmail: "agent@test.com",
      gitAuthorName: "Test Agent",
      implementationModel: "claude-sonnet-4-6",
      resultPath: "/tmp/result.json",
    });
    expect(result).toContain("Claude executor — self-briefing module");
  });

  it("contains /start-implementation instruction", () => {
    const result = generateBriefing(mgmtDir, {
      taskId: "T4",
      featureId: "executor-self-briefing",
      taskBranch: "feature/executor-self-briefing-T4",
      taskRepo: "workflow",
      taskRepoRoot: "/impl",
      workspaceRoot: mgmtDir,
      gitAuthorEmail: "agent@test.com",
      gitAuthorName: "Test Agent",
      implementationModel: "claude-sonnet-4-6",
      resultPath: "/tmp/result.json",
    });
    expect(result).toContain("/start-implementation T4");
  });

  it("contains identity section with email and name", () => {
    const result = generateBriefing(mgmtDir, {
      taskId: "T4",
      featureId: "executor-self-briefing",
      taskBranch: "feature/executor-self-briefing-T4",
      taskRepo: "workflow",
      taskRepoRoot: "/impl",
      workspaceRoot: mgmtDir,
      gitAuthorEmail: "agent@test.com",
      gitAuthorName: "Test Agent",
      implementationModel: "claude-sonnet-4-6",
      resultPath: "/tmp/result.json",
    });
    expect(result).toContain("Email: agent@test.com");
    expect(result).toContain("Name:  Test Agent");
  });

  it("contains model section", () => {
    const result = generateBriefing(mgmtDir, {
      taskId: "T4",
      featureId: "executor-self-briefing",
      taskBranch: "feature/executor-self-briefing-T4",
      taskRepo: "workflow",
      taskRepoRoot: "/impl",
      workspaceRoot: mgmtDir,
      gitAuthorEmail: "agent@test.com",
      gitAuthorName: "Test Agent",
      implementationModel: "claude-sonnet-4-6",
      resultPath: "/tmp/result.json",
    });
    expect(result).toContain("Use model: claude-sonnet-4-6");
  });

  it("falls back to taskId as title when YAML cannot be read", () => {
    const emptyDir = join(tmpdir(), `empty-${Date.now()}`);
    mkdirSync(emptyDir, { recursive: true });
    try {
      const result = generateBriefing(emptyDir, {
        taskId: "T99",
        featureId: "test-feature",
        taskBranch: "feature/test",
        taskRepo: "workflow",
        taskRepoRoot: "/impl",
        workspaceRoot: emptyDir,
        gitAuthorEmail: "agent@test.com",
        gitAuthorName: "Test Agent",
        implementationModel: "claude-sonnet-4-6",
        resultPath: "/tmp/result.json",
      });
      expect(result).toContain("T99");
    } finally {
      rmSync(emptyDir, { recursive: true, force: true });
    }
  });
});

