import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { mkdirSync, writeFileSync, rmSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { generateFixBriefing } from "../../src/briefing/fix-briefing.js";

function makeMgmtDir(taskId: string, featureId: string, title: string): string {
  const dir = join(tmpdir(), `fix-briefing-test-${Date.now()}-${Math.random().toString(36).slice(2)}`);
  const tasksDir = join(dir, "docs", "features", featureId, "tasks");
  mkdirSync(tasksDir, { recursive: true });
  writeFileSync(
    join(tasksDir, `${taskId}.yaml`),
    `id: ${taskId}\ntitle: ${title}\nrepo: workflow\nstatus: change_requested\n`,
    "utf-8",
  );
  return dir;
}

describe("generateFixBriefing", () => {
  let mgmtDir: string;

  beforeEach(() => {
    mgmtDir = makeMgmtDir("T4", "executor-self-briefing", "Claude executor — self-briefing module");
  });

  afterEach(() => {
    rmSync(mgmtDir, { recursive: true, force: true });
  });

  it("contains /respond-to-review instruction", () => {
    const result = generateFixBriefing(mgmtDir, {
      taskId: "T4",
      featureId: "executor-self-briefing",
      taskBranch: "feature/executor-self-briefing-T4",
      taskRepo: "workflow",
      taskRepoRoot: "/impl",
      workspaceRoot: mgmtDir,
      prUrl: "https://github.com/org/repo/pull/42",
      gitAuthorEmail: "agent@test.com",
      gitAuthorName: "Test Agent",
      implementationModel: "claude-sonnet-4-6",
      resultPath: "/tmp/result.json",
    });
    expect(result).toContain("/respond-to-review");
  });

  it("contains the PR URL in the briefing", () => {
    const result = generateFixBriefing(mgmtDir, {
      taskId: "T4",
      featureId: "executor-self-briefing",
      taskBranch: "feature/executor-self-briefing-T4",
      taskRepo: "workflow",
      taskRepoRoot: "/impl",
      workspaceRoot: mgmtDir,
      prUrl: "https://github.com/org/repo/pull/42",
      gitAuthorEmail: "agent@test.com",
      gitAuthorName: "Test Agent",
      implementationModel: "claude-sonnet-4-6",
      resultPath: "/tmp/result.json",
    });
    expect(result).toContain("https://github.com/org/repo/pull/42");
  });

  it("reads task title from YAML", () => {
    const result = generateFixBriefing(mgmtDir, {
      taskId: "T4",
      featureId: "executor-self-briefing",
      taskBranch: "feature/executor-self-briefing-T4",
      taskRepo: "workflow",
      taskRepoRoot: "/impl",
      workspaceRoot: mgmtDir,
      prUrl: "https://github.com/org/repo/pull/42",
      gitAuthorEmail: "agent@test.com",
      gitAuthorName: "Test Agent",
      implementationModel: "claude-sonnet-4-6",
      resultPath: "/tmp/result.json",
    });
    expect(result).toContain("Claude executor — self-briefing module");
  });
});

