describe("generateRebaseBriefing", () => {
  it("contains the task ID in the heading", () => {
    const result = generateRebaseBriefing({
      taskId: "T4",
      taskRepoBranch: "feature/executor-self-briefing-T4",
      taskBaseBranch: "feature/executor-self-briefing",
    });
    expect(result).toContain("# Rebase: T4");
  });

  it("contains the task branch name", () => {
    const result = generateRebaseBriefing({
      taskId: "T4",
      taskRepoBranch: "feature/executor-self-briefing-T4",
      taskBaseBranch: "feature/executor-self-briefing",
    });
    expect(result).toContain("feature/executor-self-briefing-T4");
  });

  it("contains the base branch name", () => {
    const result = generateRebaseBriefing({
      taskId: "T4",
      taskRepoBranch: "feature/executor-self-briefing-T4",
      taskBaseBranch: "feature/executor-self-briefing",
    });
    expect(result).toContain("feature/executor-self-briefing");
  });

  it("mentions PR conflict", () => {
    const result = generateRebaseBriefing({
      taskId: "T4",
      taskRepoBranch: "feature/executor-self-briefing-T4",
      taskBaseBranch: "feature/executor-self-briefing",
    });
    expect(result).toContain("mergeable: false");
