import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { mkdirSync, writeFileSync, rmSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { generateReviewerBriefing } from "../../src/briefing/reviewer-briefing.js";

function makeMgmtDir(taskId: string, featureId: string, title: string): string {
  const dir = join(tmpdir(), `reviewer-briefing-test-${Date.now()}-${Math.random().toString(36).slice(2)}`);
  const tasksDir = join(dir, "docs", "features", featureId, "tasks");
  mkdirSync(tasksDir, { recursive: true });
  writeFileSync(
    join(tasksDir, `${taskId}.yaml`),
    `id: ${taskId}\ntitle: ${title}\nrepo: workflow\nstatus: in_review\n`,
    "utf-8",
  );
  return dir;
}

describe("generateReviewerBriefing", () => {
  let mgmtDir: string;

  beforeEach(() => {
    mgmtDir = makeMgmtDir("T4", "executor-self-briefing", "Claude executor — self-briefing module");
  });

  afterEach(() => {
    rmSync(mgmtDir, { recursive: true, force: true });
  });

  it("contains /review-pr instruction", () => {
    const result = generateReviewerBriefing(mgmtDir, {
      taskId: "T4",
      featureId: "executor-self-briefing",
      taskBranch: "feature/executor-self-briefing-T4",
      taskRepo: "workflow",
      taskRepoRoot: "/impl",
      workspaceRoot: mgmtDir,
      prUrl: "https://github.com/org/repo/pull/42",
      gitAuthorEmail: "reviewer@test.com",
      gitAuthorName: "Reviewer Agent",
      reviewerModel: "claude-sonnet-4-6",
      resultPath: "/tmp/result.json",
      reviewCycleCount: 0,
      maxReviewCycles: 3,
    });
    expect(result).toContain("/review-pr");
  });

  it("contains review cycle information", () => {
    const result = generateReviewerBriefing(mgmtDir, {
      taskId: "T4",
