tool_use_result.originalFile:
/**
 * Integration tests for SubProcessAdapter Wave-3 (T5).
 *
 * These tests exercise the full async submit → runner callback → broker flow
 * using a real InMemoryBrokerAdapter (HTTP server) and a fake runner script
 * that simulates each scenario.
 *
 * Scenarios covered:
 *   1. Happy path — fake runner POSTs a valid result; broker.listCompleted delivers it.
 *   2. Wrapper crash before POST — runner exits without POSTing; safety net fires
 *      a synthetic "failed" completion to the broker.
 *   3. Late callback — runner sleeps before POSTing; broker still delivers the result.
 *   4. Broker-reject (replay) — runner POSTs twice; second POST (after ack) returns 401;
 *      broker.listCompleted is called only once.
 *   5. ack() removes supervision entry and cleans up result file.
 *   6. submit() returns a non-empty handle string immediately (non-blocking).
 */

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import {
  mkdtempSync,
  rmSync,
  writeFileSync,
  existsSync,
  writeFile,
} from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { promisify } from "node:util";

import { InMemoryBrokerAdapter } from "../src/adapters/broker/in-memory.js";
import { SubProcessAdapter } from "../src/adapters/executor/subprocess.js";

const writeFileAsync = promisify(writeFile);

// ── Helpers ───────────────────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeTmpDir(prefix: string): string {
  const dir = mkdtempSync(join(tmpdir(), prefix));
  tmpDirs.push(dir);
  return dir;
}

/**
 * Poll broker.listCompleted until at least one completion arrives,
 * or the timeout expires. Returns the first completion found.
 */
async function waitForCompletion(
  broker: InMemoryBrokerAdapter,
  timeoutMs = 10_000,
  pollMs = 50,
): Promise<ReturnType<typeof broker.listCompleted> extends Promise<(infer T)[]> ? T : never> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const items = await broker.listCompleted({ max: 1, lockMs: 30_000 });
    if (items.length > 0) return items[0] as any;
    await new Promise((r) => setTimeout(r, pollMs));
  }
  throw new Error(`waitForCompletion: no completion arrived within ${timeoutMs}ms`);
}

/** Build a minimal ExecutorPortInput for tests. */
function makeInput(overrides: {
  briefingPath?: string;
  resultPath: string;
  callbackUrl: string;
  nonce: string;
  handle?: string;
  taskId?: string;
  featureId?: string;
  executorWorkdir?: string;
}) {
  return {
    taskId: overrides.taskId ?? "T5",
    featureId: overrides.featureId ?? "runtime-portable-architecture",
    workspaceId: "test-ws",
    handle: overrides.handle ?? "test-handle-subprocess",
    taskRepoUrl: "git@github.com:org/repo.git",
    taskRepoBranch: "feature/runtime-portable-architecture-T5",
    executorWorkdir: overrides.executorWorkdir ?? "/tmp",
    mgmtRepoUrl: "git@github.com:org/workspace.git",
    briefingPath: overrides.briefingPath ?? "/tmp/briefing.md",
    resultPath: overrides.resultPath,
    sshPrivateKey: "",
    githubToken: "",
    callbackUrl: overrides.callbackUrl,
    nonce: overrides.nonce,
  };
}

// ── Suite setup ───────────────────────────────────────────────────────────────

let broker: InMemoryBrokerAdapter;
let callbackUrl: string;

beforeEach(async () => {
  broker = new InMemoryBrokerAdapter({ reclaimIntervalMs: 60_000 });
  await broker.start();
  callbackUrl = broker.getCallbackUrl()!;
});

afterEach(async () => {
  await broker.stop();
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
});

// ── 1. Happy path ─────────────────────────────────────────────────────────────

describe("SubProcessAdapter Wave-3 — happy path", () => {
  it("submit() returns handle immediately; broker delivers the result via callback", async () => {
    const dir = makeTmpDir("w3-happy-");
    const resultPath = join(dir, "result.json");
    const nonce = "nonce-happy-001";

    // Fake runner: reads CALLBACK_URL / HANDLE / NONCE from env and POSTs result.
    const runnerPath = join(dir, "fake-runner.cjs");
    writeFileSync(
      runnerPath,
      [
        `const http = require("node:http");`,
        `const { CALLBACK_URL, HANDLE, NONCE } = process.env;`,
        `const body = JSON.stringify({ handle: HANDLE, nonce: NONCE, result: { terminal_status: "in_review", pr_url: "https://github.com/org/repo/pull/42" } });`,
        `const url = new URL(CALLBACK_URL);`,
        `const req = http.request({`,
        `  hostname: url.hostname, port: Number(url.port), path: url.pathname,`,
        `  method: "POST",`,
        `  headers: { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) },`,
        `}, (res) => { res.resume(); process.exit(0); });`,
        `req.on("error", (e) => { process.stderr.write(e.message + "\\n"); process.exit(1); });`,
        `req.write(body); req.end();`,
      ].join("\n"),
      "utf-8",
    );

    const adapter = new SubProcessAdapter({
      runnerBinPath: runnerPath,
      broker,
      crashGraceMs: 500,
      timeoutMs: 10_000,
    });

    const handle = await adapter.submit(makeInput({ resultPath, callbackUrl, nonce }));
    expect(typeof handle).toBe("string");
    expect(handle.length).toBeGreaterThan(0);
    expect(adapter.supervisionSize()).toBe(1);

    const completion = await waitForCompletion(broker);
    expect(completion.handle).toBe(handle);
    expect(completion.result.terminal_status).toBe("in_review");
    expect((completion.result as any).pr_url).toBe("https://github.com/org/repo/pull/42");
    expect(completion.metadata.task_id).toBe("T5");

    await broker.ack(handle);
    expect(broker.queueDepth()).toBe(0);
    expect(broker.registrySize()).toBe(0);
  }, 15_000);
});

// ── 2. Wrapper crash before POST ──────────────────────────────────────────────

describe("SubProcessAdapter Wave-3 — wrapper crash before POST", () => {
  it("safety net fires synthetic failed completion when runner exits without POSTing", async () => {
    const dir = makeTmpDir("w3-crash-");
    const resultPath = join(dir, "result.json");
    const nonce = "nonce-crash-001";

    // Fake runner: exits non-zero without POSTing anything.
    const runnerPath = join(dir, "crash-runner.cjs");
    writeFileSync(runnerPath, `process.exit(1);\n`, "utf-8");

    const adapter = new SubProcessAdapter({
      runnerBinPath: runnerPath,
      broker,
      crashGraceMs: 200, // short grace for fast tests
      timeoutMs: 10_000,
    });

    const handle = await adapter.submit(makeInput({ resultPath, callbackUrl, nonce }));

    // Safety net fires crashGraceMs after child exits.
    const completion = await waitForCompletion(broker, 8_000);
    expect(completion.handle).toBe(handle);
    expect(completion.result.terminal_status).toBe("failed");
    expect(String(completion.result.blocked_reason)).toMatch(/runner_crashed/);

    await broker.ack(handle);
  }, 15_000);
});

// ── 3. Late callback ──────────────────────────────────────────────────────────

describe("SubProcessAdapter Wave-3 — late callback", () => {
  it("broker delivers result even when runner delays the POST", async () => {
    const dir = makeTmpDir("w3-late-");
    const resultPath = join(dir, "result.json");
    const nonce = "nonce-late-001";

    // Fake runner: waits 300 ms before POSTing the result.
    const runnerPath = join(dir, "late-runner.cjs");
    writeFileSync(
      runnerPath,
      [
        `const http = require("node:http");`,
        `const { CALLBACK_URL, HANDLE, NONCE } = process.env;`,
        `setTimeout(() => {`,
        `  const body = JSON.stringify({ handle: HANDLE, nonce: NONCE, result: { terminal_status: "in_review" } });`,
        `  const url = new URL(CALLBACK_URL);`,
        `  const req = http.request({`,
        `    hostname: url.hostname, port: Number(url.port), path: url.pathname,`,
        `    method: "POST",`,
        `    headers: { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) },`,
        `  }, (res) => { res.resume(); process.exit(0); });`,
        `  req.on("error", (e) => { process.stderr.write(e.message + "\\n"); process.exit(1); });`,
        `  req.write(body); req.end();`,
        `}, 300);`,
      ].join("\n"),
      "utf-8",
    );

    const adapter = new SubProcessAdapter({
      runnerBinPath: runnerPath,
      broker,
      crashGraceMs: 2_000, // longer grace than the delay so safety net doesn't fire first
      timeoutMs: 10_000,
    });

    const handle = await adapter.submit(makeInput({ resultPath, callbackUrl, nonce }));

    const completion = await waitForCompletion(broker, 8_000);
    expect(completion.handle).toBe(handle);
    expect(completion.result.terminal_status).toBe("in_review");

    await broker.ack(handle);
  }, 15_000);
});

// ── 4. Broker-reject (replay) ─────────────────────────────────────────────────

describe("SubProcessAdapter Wave-3 — broker-reject replay", () => {
  it("second POST after ack returns 401; listCompleted still delivers only one completion", async () => {
    const dir = makeTmpDir("w3-replay-");
    const resultPath = join(dir, "result.json");
    const nonce = "nonce-replay-001";

    // Fake runner: POSTs the result and then attempts a replay POST.
    const runnerPath = join(dir, "replay-runner.cjs");
    writeFileSync(
      runnerPath,
      [
        `const http = require("node:http");`,
        `const { CALLBACK_URL, HANDLE, NONCE } = process.env;`,
        ``,
        `function doPost(cb) {`,
        `  const body = JSON.stringify({ handle: HANDLE, nonce: NONCE, result: { terminal_status: "in_review" } });`,
        `  const url = new URL(CALLBACK_URL);`,
        `  const req = http.request({`,
        `    hostname: url.hostname, port: Number(url.port), path: url.pathname,`,
        `    method: "POST",`,
        `    headers: { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) },`,
        `  }, (res) => { res.resume(); cb(res.statusCode); });`,
        `  req.on("error", () => cb(-1));`,
        `  req.write(body); req.end();`,
        `}`,
        ``,
        `// First POST — should return 204`,
        `doPost((status1) => {`,
        `  // Second POST (replay) — should return 401 after broker acks`,
        `  doPost((status2) => {`,
        `    process.stderr.write(JSON.stringify({ first: status1, second: status2 }) + "\\n");`,
        `    process.exit(0);`,
        `  });`,
        `});`,
      ].join("\n"),
      "utf-8",
    );

    const adapter = new SubProcessAdapter({
      runnerBinPath: runnerPath,
      broker,
      crashGraceMs: 500,
      timeoutMs: 10_000,
    });

    const handle = await adapter.submit(makeInput({ resultPath, callbackUrl, nonce }));

    // First completion should arrive.
    const completion = await waitForCompletion(broker, 8_000);
    expect(completion.handle).toBe(handle);
    expect(completion.result.terminal_status).toBe("in_review");

    // Ack to invalidate the nonce; the replay POST (from runner) will be 401.
    await broker.ack(handle);

    // No second completion should appear in the queue (replay rejected).
    await new Promise((r) => setTimeout(r, 300));
    const second = await broker.listCompleted({ max: 1 });
    expect(second).toHaveLength(0);
  }, 15_000);
});

// ── 5. ack() cleans up supervision and result file ────────────────────────────

describe("SubProcessAdapter Wave-3 — ack cleanup", () => {
  it("adapter.ack() removes supervision entry and deletes the result file", async () => {
    const dir = makeTmpDir("w3-ack-");
    const resultPath = join(dir, "result.json");
    const nonce = "nonce-ack-001";

    // Fake runner: POSTs result AND writes the result file so ack can delete it.
    const runnerPath = join(dir, "ack-runner.cjs");
    writeFileSync(
      runnerPath,
      [
        `const http = require("node:http");`,
        `const fs = require("node:fs");`,
        `const { CALLBACK_URL, HANDLE, NONCE, RESULT_PATH } = process.env;`,
        `fs.writeFileSync(RESULT_PATH, JSON.stringify({ terminal_status: "in_review" }));`,
        `const body = JSON.stringify({ handle: HANDLE, nonce: NONCE, result: { terminal_status: "in_review" } });`,
        `const url = new URL(CALLBACK_URL);`,
        `const req = http.request({`,
        `  hostname: url.hostname, port: Number(url.port), path: url.pathname,`,
        `  method: "POST",`,
        `  headers: { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) },`,
        `}, (res) => { res.resume(); process.exit(0); });`,
        `req.on("error", () => process.exit(1));`,
        `req.write(body); req.end();`,
      ].join("\n"),
      "utf-8",
    );

    const adapter = new SubProcessAdapter({
      runnerBinPath: runnerPath,
      broker,
      crashGraceMs: 500,
      timeoutMs: 10_000,
    });

    const handle = await adapter.submit(makeInput({ resultPath, callbackUrl, nonce }));
    expect(adapter.supervisionSize()).toBe(1);

    // Wait for the callback.
    await waitForCompletion(broker, 8_000);

    // The result file should exist (written by the executor via runner).
    // Give it a moment to be written.
    await new Promise((r) => setTimeout(r, 100));
    expect(existsSync(resultPath)).toBe(true);

    // ack via adapter removes supervision entry, deletes file, and calls broker.ack.
    await adapter.ack(handle);

    expect(adapter.supervisionSize()).toBe(0);
    expect(existsSync(resultPath)).toBe(false);
    expect(broker.queueDepth()).toBe(0);
    expect(broker.registrySize()).toBe(0);
  }, 15_000);
});

// ── 6. submit() is non-blocking ───────────────────────────────────────────────

describe("SubProcessAdapter Wave-3 — non-blocking submit", () => {
  it("submit() resolves before the runner finishes (fast return)", async () => {
    const dir = makeTmpDir("w3-nonblock-");
    const resultPath = join(dir, "result.json");
    const nonce = "nonce-nonblock-001";

    // Fake runner: sleeps for 500 ms then exits.
    const runnerPath = join(dir, "slow-runner.cjs");
    writeFileSync(
      runnerPath,
      [
        `const http = require("node:http");`,
        `const { CALLBACK_URL, HANDLE, NONCE } = process.env;`,
        `setTimeout(() => {`,
        `  const body = JSON.stringify({ handle: HANDLE, nonce: NONCE, result: { terminal_status: "in_review" } });`,
        `  const url = new URL(CALLBACK_URL);`,
        `  const req = http.request({`,
        `    hostname: url.hostname, port: Number(url.port), path: url.pathname,`,
        `    method: "POST",`,
        `    headers: { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) },`,
        `  }, (res) => { res.resume(); process.exit(0); });`,
        `  req.on("error", () => process.exit(1));`,
        `  req.write(body); req.end();`,
        `}, 500);`,
      ].join("\n"),
      "utf-8",
    );

    const adapter = new SubProcessAdapter({
      runnerBinPath: runnerPath,
      broker,
      crashGraceMs: 2_000,
      timeoutMs: 10_000,
    });

    const before = Date.now();
    const handle = await adapter.submit(makeInput({ resultPath, callbackUrl, nonce }));
    const elapsed = Date.now() - before;

    // submit() should return well before the runner's 500 ms sleep.
    expect(elapsed).toBeLessThan(400);
    expect(typeof handle).toBe("string");

    // Clean up: wait for the runner to finish.
    await waitForCompletion(broker, 8_000);
    await broker.ack(handle);
  }, 15_000);
});

/**
 * Seam tests: orchestrator dispatch + FakeAdapter.
 *
 * These tests exercise the ABI seam — the boundary between the adapter
 * (which produces an ExecutorResult) and the orchestrator's side-effect
 * dispatcher (which translates that result into task YAML mutations).
 *
 * Uses dispatchExecutorResult (extracted from main.ts) so the full
 * bootstrap + poll loop does not need to run.
 *
 * Revised D5: the executor owns impl-PR creation; the orchestrator only
 * records the pr_url reported in result.json. No curl/GitHub API calls are
 * made by the orchestrator for impl PRs.
 *
 * FakeAdapter scenarios:
 *   1. in_review with pr_url → task in_review, pr.url recorded, draft PR promoted to ready-for-review
 *   2. in_review without pr_url → task in_review, no pr.url set, no PATCH call
 *   3. blocked with pr_url → task blocked, pr.url still recorded (draft PR), no PATCH
 *   4. blocked with reason + suggestion → task marked blocked
 *   5. failed with executor_crashed reason → task blocked with executor_failed prefix
 *   6. failed with result_schema_invalid reason → task blocked with executor_failed prefix
 *   7. cost data — in_review with token_usage + cost_usd → run_completed log entry persists cost
 *   8. cost data — in_review without token_usage/cost_usd → run_completed log entry has no cost
 *   9. cost data — blocked with token_usage + cost_usd → blocked log entry persists cost
 *  10. in_review with pr_url, PATCH fails → task_pr_promote_failed emitted, task still in_review
 */

import { describe, it, expect, vi, afterEach } from "vitest";
